import React from "react";
import DialogFeaturesTitle from "src/views/dialog/IT-Solution-Features/DialogFeaturesTitle";
import TableFeaturesTitle from "src/views/tables/IT-Solution-Features/TableFeaturesTitle";
import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  CardContent,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints, MEDIA_URL } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useParams } from "react-router-dom";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import DialogOverviewImages from "src/views/dialog/IT-Solution-Overview/DialogOverviewImages";

const ITSolutionOverviewImages = () => {
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const [overviewImages, setOverviewImages] = useState([]);
  const [addImageDialogOpen, setAddImageDialogOpen] = useState(false);
  const [addImageDialogMode, setAddImageDialogMode] = useState("add");
  const [imageToEdit, setImageToEdit] = useState(null);
  const [images, setImages] = useState([]);

  const toggleAddImageFormDialog = (e, mode = "add", imagetoEdit = null) => {
    setAddImageDialogOpen((prev) => !prev);
    setAddImageDialogMode(mode);
    setImageToEdit(imagetoEdit);
  };

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [imageToDelete, setImageToDelete] = useState(null);
  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setImageToDelete(dataToDelete);
  };

  const fetchData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewImages.list(id), {})
      .then((response) => {
        const responseData = response.data.data;

        setOverviewImages(responseData);
        // const allImages = responseData.flatMap((item) => item.images);
        // setImages(allImages);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData();
  }, []);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(ApiEndPoints.ITSolutionOverviewImages.delete(imageToDelete.id))
        .then((response) => response.data)
        .then((response) => {
          fetchData();
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [imageToDelete]
  );
  return (
    <>
      <Box>
        <PageHeader
          title={<Typography variant="h5">Overview Images</Typography>}
          action={
            <Button variant="contained" onClick={toggleAddImageFormDialog}>
              Add Image
            </Button>
          }
        />
        <Box
          mt={5}
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 5,
            flexWrap: "wrap",
          }}
        >
          {overviewImages?.map((item, index) => (
            <Card key={index}>
              <CardContent>
                <Box sx={{ height: "250px", width: "250px" }}>
                  <img
                    src={
                      item.image_url
                        ? item.image_url.startsWith(
                            "https://dwitst24.blob.core.windows.net/upload/"
                          )
                          ? item.image_url.replace(
                              "https://dwitst24.blob.core.windows.net/upload/",
                              MEDIA_URL
                            )
                          : item.image_url.startsWith("http")
                          ? item.image_url
                          : `${MEDIA_URL}${item.image_url}`
                        : "" // Fallback in case icon_image is null or empty
                    }
                    style={{
                      height: "100%",
                      width: "100%",
                      objectFit: "fill",
                    }}
                  />
                </Box>
                <Box display="flex" alignItems="center" gap="10px">
                  <IconButton
                    size="small"
                    color="primary"
                    variant="outlined"
                    onClick={(e) => toggleAddImageFormDialog(e, "edit", item)}
                  >
                    <EditIcon />
                  </IconButton>
                  <IconButton
                    size="small"
                    color="secondary"
                    onClick={(e) => toggleConfirmationDialog(e, item)}
                    // onClick={(e) => toggleDelete(e, row)}
                  >
                    <DeleteIcon />
                  </IconButton>
                </Box>
              </CardContent>
            </Card>
          ))}
        </Box>
      </Box>
      <DialogOverviewImages
        mode={addImageDialogMode}
        open={addImageDialogOpen}
        toggle={toggleAddImageFormDialog}
        dataToEdit={imageToEdit}
        itSolutionId={id}
        onSuccess={() => {
          fetchData();
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Image"
        subtitle="Are you sure you want to delete this Image?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionOverviewImages;
